ALTER TABLE accounts ADD COLUMN enabled BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE mail_jobs ADD COLUMN appointment_id BIGINT REFERENCES appointments(id);
ALTER TABLE mail_jobs ADD COLUMN created_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE mail_jobs ADD COLUMN sent_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE mail_jobs ADD COLUMN last_error VARCHAR(1000);
CREATE TABLE guest_links (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, appointment_id BIGINT NOT NULL REFERENCES appointments(id), hash VARCHAR(255) NOT NULL UNIQUE, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, revoked BOOLEAN NOT NULL);
CREATE TABLE schedule_templates (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, doctor_id BIGINT NOT NULL REFERENCES doctors(id), name VARCHAR(150) NOT NULL, minutes INTEGER NOT NULL, rules VARCHAR(12000) NOT NULL);
CREATE TABLE audit_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id BIGINT REFERENCES accounts(id), actor_name VARCHAR(255) NOT NULL, action VARCHAR(255) NOT NULL, entity_type VARCHAR(255) NOT NULL, entity_id BIGINT, doctor_id BIGINT REFERENCES doctors(id), details VARCHAR(4000) NOT NULL, occurred_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX audit_doctor_time ON audit_events(doctor_id, occurred_at);
CREATE INDEX mail_appointment ON mail_jobs(appointment_id);
